// WP-5.3 cluster streaming on the GPU: see include/fuse/renderer/geometry_streaming/geometry_streaming.hpp.
#include <fuse/renderer/geometry_streaming/geometry_streaming.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>
#include <fuse/renderer/vk/upload_queue.hpp>

#include <algorithm>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp53.cmake from src/geometry_streaming/shaders/*: kStreamCut<Slang|Glsl>Spv and
// FUSE_STREAM_{SLANG,GLSL} when the kernel of a language exists.
#include "stream_spv.h"
#endif

namespace fuse::renderer::geometry_streaming {

namespace {
[[maybe_unused]] constexpr u32 kUpdateChunk = 65536u; ///< vkCmdUpdateBuffer limit

[[maybe_unused]] u32 groups(u32 items, u32 size) { return items == 0u ? 1u : (items + size - 1u) / size; }

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
#endif
} // namespace

StreamingCapabilities queryStreamingCapabilities(const VulkanDevice* device) {
    StreamingCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    if (!device->info().caps.bufferDeviceAddress) {
        c.reason = "bufferDeviceAddress missing";
        return c;
    }
    c.ok = true;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

GeometryStreaming::~GeometryStreaming() { destroy(); }

bool GeometryStreaming::init(const GeometryStreamingDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.bindless == nullptr || desc.upload == nullptr || desc.dag == nullptr ||
        desc.file == nullptr || desc.framesInFlight == 0u || !queryStreamingCapabilities(desc.device).ok) {
        return false;
    }
    const ClusterPageFile& file = *desc.file;
    const geometry::dag::ClusterDag& dag = *desc.dag;
    if (file.cluster_count != dag.cluster_count() || file.links_hash != cluster_links_hash(dag) ||
        !m_streamer.init(file, desc.streamer)) {
        return false;
    }
    m_clusterCount = file.cluster_count;
    m_pageCount = file.page_count();
    m_bitWords = (m_pageCount + 31u) / 32u;
    m_layout = stream_kernel::feedback_layout(m_pageCount);
    m_stateHost.assign(static_cast<usize>(m_bitWords) + m_pageCount, 0u);
    m_ringSerial.assign(desc.framesInFlight, 0u);
    m_pending.assign(m_streamer.slot_count(), PendingUpload{});
    m_pendingCount = 0;
    m_initialized = true; // destroy() releases partial state from here on
    std::vector<StreamClusterInfo> info;
    build_stream_cluster_info(dag, file, info);
    const u64 feedbackBytes = static_cast<u64>(m_layout.words) * 4u;
    if (!createPipeline() ||
        !createBuffer(m_links, dag.links.size() * sizeof(dag.links[0]), true, MemoryUsage::GpuOnly, "stream.links") ||
        !createBuffer(m_info, info.size() * sizeof(StreamClusterInfo), true, MemoryUsage::GpuOnly, "stream.info") ||
        !createBuffer(m_state, m_stateHost.size() * 4u, true, MemoryUsage::GpuOnly, "stream.state") ||
        !createBuffer(m_feedback, feedbackBytes, true, MemoryUsage::GpuOnly, "stream.feedback") ||
        !createBuffer(m_cut, static_cast<u64>(m_clusterCount) * 4u, true, MemoryUsage::GpuOnly, "stream.cut") ||
        !createBuffer(m_drawList, static_cast<u64>(m_clusterCount) * 4u, true, MemoryUsage::GpuOnly, "stream.draw_list") ||
        !createBuffer(m_pool, static_cast<u64>(m_streamer.slot_count()) * file.page_bytes, false, MemoryUsage::GpuOnly,
                      "stream.pool") ||
        !createBuffer(m_readback, feedbackBytes * desc.framesInFlight, false, MemoryUsage::GpuToCpu, "stream.feedback_readback") ||
        m_readback.buffer.mapped == nullptr) {
        destroy();
        return false;
    }
    if (!uploadBlob(m_links, dag.links.data(), dag.links.size() * sizeof(dag.links[0])) ||
        !uploadBlob(m_info, info.data(), info.size() * sizeof(StreamClusterInfo))) {
        destroy();
        return false;
    }
    // Coarse LOD before the first frame: load, upload and wait (coarse pages have no dependencies).
    u32 frame = 1;
    while (!m_streamer.coarse_resident() && frame <= m_pageCount + 1u) {
        if (!m_streamer.begin_frame(frame, frame - 1u)) {
            break;
        }
        m_streamer.update();
        if (!issueLoads()) {
            break;
        }
        m_desc.upload->flush();
        if (!m_desc.upload->waitAll()) {
            break;
        }
        pollUploads();
        ++frame;
    }
    if (!m_streamer.coarse_resident()) {
        destroy();
        return false;
    }
    m_frameOffset = frame;
    m_stats = StreamGpuStats{};
    return true;
#else
    return false;
#endif
}

void GeometryStreaming::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    destroyBuffer(m_links);
    destroyBuffer(m_info);
    destroyBuffer(m_state);
    destroyBuffer(m_feedback);
    destroyBuffer(m_cut);
    destroyBuffer(m_drawList);
    destroyBuffer(m_pool);
    destroyBuffer(m_readback);
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    if (m_pipeline != nullptr) {
        vkDestroyPipeline(device, static_cast<VkPipeline>(m_pipeline), nullptr);
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_pipeline = nullptr;
    m_layoutHandle = nullptr;
    m_language = "none";
    m_stateHost.clear();
    m_ringSerial.clear();
    m_pending.clear();
    m_pendingCount = 0;
    m_recordCount = 0;
    m_serial = m_lastConsumed = m_lastRecorded = 0;
    m_stats = StreamGpuStats{};
    m_initialized = false;
}

bool GeometryStreaming::createPipeline() {
#if defined(FUSE_VULKAN_BACKEND)
    Code k{};
    bool found = false;
#if defined(FUSE_STREAM_SLANG)
    if (m_desc.language == StreamKernelLanguage::Auto || m_desc.language == StreamKernelLanguage::Slang) {
        k = code(kStreamCutSlangSpv);
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_STREAM_GLSL)
    if (!found && (m_desc.language == StreamKernelLanguage::Auto || m_desc.language == StreamKernelLanguage::Glsl)) {
        k = code(kStreamCutGlslSpv);
        m_language = "glsl";
        found = true;
    }
#endif
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(StreamCutPush)};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    VkShaderModuleCreateInfo moduleInfo{};
    moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    moduleInfo.codeSize = k.bytes;
    moduleInfo.pCode = k.words;
    VkShaderModule module = VK_NULL_HANDLE;
    if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
        return false;
    }
    VkComputePipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
    info.flags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
    info.stage.module = module;
    info.stage.pName = "main";
    info.layout = layout;
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    vkDestroyShaderModule(device, module, nullptr);
    m_pipeline = pipeline;
    return result == VK_SUCCESS;
#else
    return false;
#endif
}

bool GeometryStreaming::createBuffer(OwnedBuffer& out, u64 bytes, bool bindless, MemoryUsage memory, const char* name) {
    out = OwnedBuffer{};
    BufferDesc desc{};
    desc.size = static_cast<usize>(std::max<u64>(bytes, 16u));
    const bool readback = memory == MemoryUsage::GpuToCpu;
    desc.usage = static_cast<BufferUsage>(
        readback ? static_cast<u32>(BufferUsage::TransferDst)
                 : static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::TransferDst) |
                       static_cast<u32>(BufferUsage::TransferSrc) | static_cast<u32>(BufferUsage::ShaderDeviceAddress));
    desc.memoryUsage = memory;
    desc.name = name;
    if (!m_desc.allocator->createBuffer(desc, out.buffer) || (!readback && out.buffer.deviceAddress == 0u)) {
        if (out.buffer.handle != nullptr) {
            m_desc.allocator->destroyBuffer(out.buffer);
        }
        out = OwnedBuffer{};
        return false;
    }
    if (bindless) {
        out.slot = m_desc.bindless->registerBufferSlot(out.buffer, false);
        out.handle = m_desc.bindless->shaderHandle(out.slot);
        if (!out.slot.isValid()) {
            destroyBuffer(out);
            return false;
        }
    }
    return true;
}

void GeometryStreaming::destroyBuffer(OwnedBuffer& b) {
    if (b.slot.isValid()) {
        m_desc.bindless->unregisterSlot(b.slot);
    }
    if (b.buffer.handle != nullptr) {
        m_desc.allocator->destroyBuffer(b.buffer);
    }
    b = OwnedBuffer{};
}

bool GeometryStreaming::uploadBlob(OwnedBuffer& dst, const void* data, u64 bytes) {
    // Chunks of at most a quarter of the ring, so a large DAG streams through a small staging ring.
    const u64 chunk = std::max<u64>(4096u, (m_desc.upload->ringCapacity() / 4u) & ~u64{15u});
    for (u64 at = 0; at < bytes; at += chunk) {
        const u64 n = std::min(chunk, bytes - at);
        usize offset = 0;
        if (!m_desc.upload->stage(static_cast<const u8*>(data) + at, static_cast<usize>(n), offset) ||
            !m_desc.upload->recordBufferCopy(dst.buffer.handle, offset, static_cast<usize>(at), static_cast<usize>(n))) {
            return false;
        }
    }
    m_desc.upload->flush();
    return m_desc.upload->waitAll();
}

bool GeometryStreaming::issueLoads() {
    const ClusterPageFile& file = *m_desc.file;
    for (u32 i = 0; i < m_streamer.load_count(); ++i) {
        const u32 page = m_streamer.load_page(i);
        const u32 slot = m_streamer.load_slot(i);
        const u32 bytes = file.pages[page].payload_bytes;
        usize offset = 0;
        if (!m_desc.upload->stage(file.page_payload(page), bytes, offset) ||
            !m_desc.upload->recordBufferCopy(m_pool.buffer.handle, offset, static_cast<usize>(slot) * file.page_bytes, bytes)) {
            m_streamer.fail_load(page);
            ++m_stats.uploadFailures;
            continue;
        }
        if (m_pendingCount >= m_pending.size()) {
            return false;
        }
        m_pending[m_pendingCount++] = PendingUpload{page, m_desc.upload->pendingTicket().serial};
        ++m_stats.uploadsIssued;
    }
    return true;
}

void GeometryStreaming::pollUploads() {
    u32 keep = 0;
    for (u32 i = 0; i < m_pendingCount; ++i) {
        UploadTicket t{};
        t.serial = m_pending[i].ticketSerial;
        t.accepted = true;
        if (t.serial == 0u || m_desc.upload->isComplete(t)) {
            m_streamer.complete_load(m_pending[i].page);
            ++m_stats.uploadsCompleted;
        } else {
            m_pending[keep++] = m_pending[i];
        }
    }
    m_pendingCount = keep;
}

const u32* GeometryStreaming::feedbackHost(u64 serial) const {
    if (!m_initialized || serial == 0u) {
        return nullptr;
    }
    const u32 slot = static_cast<u32>(serial % m_desc.framesInFlight);
    if (m_ringSerial[slot] != serial) {
        return nullptr;
    }
    return reinterpret_cast<const u32*>(static_cast<const u8*>(m_readback.buffer.mapped) +
                                        static_cast<u64>(slot) * m_layout.words * 4u);
}

bool GeometryStreaming::beginFrame(u64 serial, const geometry::dag::cut_kernel::DagView& view, u64 completedSerial) {
    if (!m_initialized || serial <= m_serial) {
        return false;
    }
    m_serial = serial;
    m_recordCount = 0;
    m_stats.uploadsIssued = 0;
    m_stats.uploadsCompleted = 0;
    m_stats.uploadFailures = 0;
    m_stats.feedbackSerial = 0;
    m_stats.passes = 0;
    pollUploads();
    const u32 frame = static_cast<u32>(serial) + m_frameOffset;
    const u32 completedFrame = static_cast<u32>(std::min(completedSerial, serial - 1u)) + m_frameOffset;
    if (!m_streamer.begin_frame(frame, completedFrame)) {
        return false;
    }
    // Newest finished frame's feedback (older ones are superseded).
    const u64 newest = std::min(completedSerial, m_lastRecorded);
    if (newest > m_lastConsumed) {
        const u32* words = feedbackHost(newest);
        if (words != nullptr) {
            m_streamer.apply_feedback(words, m_layout.words);
            ++m_stats.feedbackFrames;
            m_stats.feedbackSerial = newest;
        }
        m_lastConsumed = newest;
    }
    m_streamer.update();
    const bool issued = issueLoads();
    // This frame's state: resident bits + slot table.
    std::copy(m_streamer.resident_bits(), m_streamer.resident_bits() + m_bitWords, m_stateHost.begin());
    std::copy(m_streamer.slot_table(), m_streamer.slot_table() + m_pageCount, m_stateHost.begin() + m_bitWords);
    m_view = view;
    StreamCutPush p{};
    for (u32 a = 0; a < 3u; ++a) {
        p.camera[a] = view.camera[a];
    }
    p.errorScale = view.error_scale;
    p.threshold = view.threshold;
    p.znear = view.znear;
    p.clusterCount = m_clusterCount;
    p.pageCount = m_pageCount;
    p.links = m_links.handle;
    p.info = m_info.handle;
    p.state = m_state.handle;
    p.feedback = m_feedback.handle;
    p.cut = m_cut.handle;
    p.drawList = m_drawList.handle;
    m_push = p;
    return issued;
}

StreamGraphRefs GeometryStreaming::importInto(rg::Graph& graph) {
    StreamGraphRefs refs{};
    if (!m_initialized) {
        return refs;
    }
    auto import = [&](OwnedBuffer& b, const char* name) {
        return graph.importBuffer(rg::ImportedBuffer{b.buffer.handle, b.buffer.desc.size, b.queue, &b.queue, name});
    };
    refs.links = import(m_links, "stream.links");
    refs.info = import(m_info, "stream.info");
    refs.state = import(m_state, "stream.state");
    refs.feedback = import(m_feedback, "stream.feedback");
    refs.cut = import(m_cut, "stream.cut");
    refs.drawList = import(m_drawList, "stream.draw_list");
    refs.pool = import(m_pool, "stream.pool");
    refs.readback = import(m_readback, "stream.feedback_readback");
    return refs;
}

void GeometryStreaming::addFrame(rg::Graph& graph, const StreamGraphRefs& refs) {
    if (!m_initialized || !refs.state.valid() || m_recordCount + 3u > kMaxPasses) {
        return;
    }
    auto next = [&](RecordKind kind) {
        PassRecord* r = &m_records[m_recordCount++];
        r->self = this;
        r->kind = kind;
        ++m_stats.passes;
        return r;
    };
    graph.addPass("stream.state", &GeometryStreaming::recordPass, next(kState))
        .use(refs.state, rg::Access::TransferDst)
        .use(refs.feedback, rg::Access::TransferDst);
    graph.addPass("stream.cut", &GeometryStreaming::recordPass, next(kCut))
        .use(refs.links, rg::Access::StorageRead, {}, rg::kStageCompute)
        .use(refs.info, rg::Access::StorageRead, {}, rg::kStageCompute)
        .use(refs.state, rg::Access::StorageRead, {}, rg::kStageCompute)
        .use(refs.feedback, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
        .use(refs.cut, rg::Access::StorageWrite, {}, rg::kStageCompute)
        .use(refs.drawList, rg::Access::StorageWrite, {}, rg::kStageCompute);
    const u64 bytes = static_cast<u64>(m_layout.words) * 4u;
    const u32 slot = static_cast<u32>(m_serial % m_desc.framesInFlight);
    const rg::BufferRange range{static_cast<u64>(slot) * bytes, bytes};
    graph.addPass("stream.feedback", &GeometryStreaming::recordPass, next(kFeedbackCopy))
        .use(refs.feedback, rg::Access::TransferSrc)
        .use(refs.readback, rg::Access::TransferDst, range);
    graph.addPass("stream.feedback_host", nullptr, nullptr).use(refs.readback, rg::Access::HostRead, range);
    m_ringSerial[slot] = m_serial;
    m_lastRecorded = m_serial;
}

void GeometryStreaming::recordPass(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const GeometryStreaming& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    switch (r.kind) {
    case kState: {
        const u64 total = static_cast<u64>(self.m_stateHost.size()) * 4u;
        const u8* src = reinterpret_cast<const u8*>(self.m_stateHost.data());
        for (u64 at = 0; at < total; at += kUpdateChunk) {
            const u64 n = std::min<u64>(kUpdateChunk, total - at);
            vkCmdUpdateBuffer(cmd, static_cast<VkBuffer>(self.m_state.buffer.handle), at, n, src + at);
        }
        vkCmdFillBuffer(cmd, static_cast<VkBuffer>(self.m_feedback.buffer.handle), 0, VK_WHOLE_SIZE, 0u);
        return;
    }
    case kCut:
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipeline));
        self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
        vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0,
                           sizeof(StreamCutPush), &self.m_push);
        vkCmdDispatch(cmd, groups(self.m_clusterCount, stream_kernel::kWorkgroup), 1u, 1u);
        return;
    case kFeedbackCopy: {
        const u64 bytes = static_cast<u64>(self.m_layout.words) * 4u;
        const u32 slot = static_cast<u32>(self.m_serial % self.m_desc.framesInFlight);
        const VkBufferCopy region{0, static_cast<u64>(slot) * bytes, bytes};
        vkCmdCopyBuffer(cmd, static_cast<VkBuffer>(self.m_feedback.buffer.handle),
                        static_cast<VkBuffer>(self.m_readback.buffer.handle), 1, &region);
        return;
    }
    }
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::geometry_streaming
